function brand(){return `<a class="brand" href="index.html" aria-label="${esc(C.companyName)} home">${brandMark()}<span class="brand-wordmark"><strong data-company>${esc(C.companyName)}</strong><small>HOME SECURITY</small></span></a>`;}
function header(){return `<div class="topbar"><div class="container"><div class="topbar-notes"><span>${icon('house')} Home security, thoughtfully explored</span><span>${icon('check')} Independent discovery</span></div><a data-email href="mailto:${esc(C.email)}">${icon('email')}${esc(C.email)}</a></div></div><header class="header"><div class="container nav-wrap">${brand()}<nav id="navigation" aria-label="Main navigation"><a href="index.html" ${page==='index'?'aria-current="page"':''}>Home</a><a href="about.html" ${page==='about'?'aria-current="page"':''}>About us</a><div class="dropdown"><button class="services-toggle" aria-expanded="false" aria-controls="services-menu">Services <span class="chevron"></span></button><div class="dropdown-panel" id="services-menu">${services.map(s=>`<a href="${s.key}.html">${icon(s.icon)}${s.name}</a>`).join('')}</div></div><a href="index.html#home-notes">Home guide</a><a href="contact.html" ${page==='contact'?'aria-current="page"':''}>Contact</a></nav><button class="search-toggle" aria-label="Search the website"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5" stroke="currentColor" stroke-width="1.6"/><path d="m16 16 5 5" stroke="currentColor" stroke-width="1.6"/></svg></button><button class="burger" aria-label="Open menu" aria-controls="navigation" aria-expanded="false"><span></span><span></span></button></div></header><dialog id="site-search"><div class="search-inner"><button class="search-close" aria-label="Close search"><span class="plus"></span></button><h2>Find your direction.</h2><label>Search home security<input id="search-input" type="search" placeholder="Cameras, alarms, smart access…" autocomplete="off"></label><div id="search-results"></div></div></dialog>`;}

