function carousel(items,cls=''){return `<div class="carousel ${cls}" data-aos="fade-up"><div class="swiper"><div class="swiper-wrapper">${items.map(x=>`<article class="swiper-slide">${x}</article>`).join('')}</div></div><div class="slider-controls"><div class="swiper-pagination"></div><div><button class="slider-prev" aria-label="Previous slide">${arrow}</button><button class="slider-pause" aria-label="Pause slideshow">${pauseIcon}</button><button class="slider-next" aria-label="Next slide">${arrow}</button></div></div></div>`;}
function faq(items){return `<div class="faq-list">${items.map(([q,a],i)=>`<div class="faq-item"><h3><button aria-expanded="false" aria-controls="answer-${i}"><span class="faq-label">${q}</span><span class="plus" aria-hidden="true"></span></button></h3><div class="answer" id="answer-${i}" inert><div><p>${a}</p></div></div></div>`).join('')}</div>`;}
function cta(title='Make home feel like home.',text='Tell us about your property and the security options you want to explore.'){return `<div class="cta-box"><div><h2 data-title>${title}</h2><p>${text}</p></div>${btn('Start a conversation')}</div>`;}
