function about(){return `
${wrap('about-hero','about-hero soft ref-about',`<div class="split"><div><h1>A clearer path.<br>A safer feeling.</h1><p class="lead"><span data-company>${esc(C.companyName)}</span> helps people explore home security with a little more clarity and a lot less guesswork.</p><p>We bring the starting points together: cameras, alarms and smart access. You bring the details that make your home yours.</p>${btn('Explore the options','index.html#security')}</div><div class="about-image">${img('hero2','', 'Security professional beside a vehicle',true)}<div class="image-label">Your home comes first.</div></div></div>`)}
${aboutExtras('perspective')}
${wrap('our-purpose','',`<div class="split"><div class="purpose-photo">${img('homeArt','','Home security architectural illustration')}<span class="purpose-caption">Thoughtfully explored.<br>Independently chosen.</span></div><div>${heading('Clarity before commitment.','Choosing a system can mean comparing unfamiliar features, different installation approaches and ongoing plans.')}<p>Our role is to make that first step easier. Explore the services, consider your priorities and send a brief that explains what matters to you.</p><p>We do not install or monitor systems. Independent providers are responsible for their advice, equipment, quotes and services. You decide whether their proposal is right for your home.</p><a class="text-link" href="contact.html">Start with your questions</a></div></div>`)}
${aboutExtras('journey')}
${wrap('our-values','navy',`<div class="values-grid">${[['shield','Independence','Explore directions without a one-size-fits-all recommendation. A provider introduction is a starting point for your own assessment.'],['privacy','Respect for privacy','Share only the details needed for your enquiry. Avoid including entry codes, security credentials or sensitive household information.'],['check','Useful clarity','Understand the scope, practical requirements and ongoing costs before you make a decision about equipment or services.']].map((x,i)=>`<article tabindex="0">${img(['house','interior','hero2'][i],'value-photo','')}${icon(x[0])}<h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div>`)} `;}
function contact(){return `
${wrap('contact-hero','contact-hero navy photo-title',`<h1>Let’s talk home security.</h1><p>Tell us what you have in mind.<br>We’ll help you frame the next conversation.</p><a data-email href="mailto:${esc(C.email)}">${esc(C.email)}</a>`)}
${wrap('your-enquiry','contact-section',`<div class="contact-layout"><aside>${img('contact','contact-photo','Security consultant with a tablet')}<h2>Your home.<br>Your priorities.</h2><p>Start with your property type, the areas you want to consider and any equipment already in place.</p><p>There is no obligation to proceed. Please do not include entry codes, passwords or other sensitive security details.</p></aside><form id="contact-form" action="contact.php" method="post"><h2>Start a conversation.</h2><p>A few details are all we need to get started.</p><div class="form-grid"><label>Your name<input name="name" autocomplete="name" minlength="2" maxlength="100" placeholder="Full name" required></label><label>Email address<input name="email" type="email" autocomplete="email" maxlength="254" placeholder="you@example.com" required></label></div><div class="form-grid service-field-row"><label class="service-field">Service<select name="service" required><option value="">Choose a service</option>${services.map(s=>`<option value="${s.key}">${s.name}</option>`).join('')}<option value="combined">A combination of services</option><option value="general">A general question</option></select></label><label>Property type<input name="property" maxlength="100" placeholder="House, apartment…" autocomplete="off"></label></div><label>Your message<textarea name="message" minlength="10" maxlength="5000" rows="5" placeholder="Tell us a little about your home and your priorities…" required></textarea></label><div class="honeypot" aria-hidden="true"><label>Leave blank<input name="website_check" tabindex="-1" autocomplete="off"></label></div><label class="consent"><input type="checkbox" name="privacy_consent" value="1" required><span>I have read the <a href="privacy.html" target="_blank" rel="noopener">Privacy Policy</a> and agree to the use of my details to respond to this enquiry.</span></label><button class="btn" type="submit">Send enquiry</button><p id="form-status" role="status" aria-live="polite"></p></form></div>`)}${contactCards()} `;}
const legalContent={
 privacy:{title:'Privacy Policy',intro:'How we use information you choose to share.',blocks:[['Who we are',`${esc(C.legalName)} operates this independent home security discovery website. Contact us at <a data-email href="mailto:${esc(C.email)}">${esc(C.email)}</a> with questions about your information.`],['Information you provide','The enquiry form collects your name, email address, service interest, optional property type and message. Please do not send passwords, access codes, payment details or sensitive security information.'],['How information is used','We use enquiry details to read and respond to your request and discuss a possible next step. We do not use this form to subscribe you to marketing.'],['Provider introductions','If a provider introduction is relevant, we will explain the proposed sharing before forwarding your enquiry. Equipment and services are supplied by independent providers under their own terms and privacy practices.'],['Website services','The website may request fonts from external hosting services. Photo files and interface libraries are served with this website. These services receive technical information such as your IP address when your browser requests an asset. No advertising trackers or analytics have been added to this website.'],['Retention and access','Enquiries should be kept only for as long as needed to handle the request and any applicable record-keeping requirements. Contact us to ask about access, correction or deletion of information you provided.'],['Your choices','You can choose not to submit an enquiry and can contact us by email instead. Your available data rights depend on the rules that apply to you. Contact the relevant data protection authority if you have concerns.']]},
 terms:{title:'Terms of Use',intro:'The role of the platform and your choices.',blocks:[['About the platform',`${esc(C.legalName)} offers general information and an enquiry route for people exploring home security. The platform does not supply, install, monitor or maintain security equipment.`],['Information and suitability','Content is a starting point for your own enquiries. Equipment compatibility, coverage and suitability depend on your property and should be assessed by the provider you choose.'],['Enquiries and introductions','Submitting a form does not create a service agreement or guarantee a provider match, response time or availability. You are not required to accept any proposal.'],['Independent providers','Any quote, installation, monitoring agreement, warranty or payment arrangement is between you and the chosen provider. Review their scope, credentials, terms, charges and support arrangements before proceeding.'],['Responsible use','Do not misuse the form, submit unlawful material or attempt to gain unauthorised access to the website. Use accurate contact details and avoid sharing confidential security information.'],['Availability and changes','Content and available enquiry options may change. The website may be temporarily unavailable for maintenance or other operational reasons. Nothing here is intended to remove rights that cannot lawfully be excluded.'],['Contact',`Questions about these terms can be sent to <a data-email href="mailto:${esc(C.email)}">${esc(C.email)}</a>.`]]},
 cookies:{title:'Cookie Policy',intro:'A small preference. A transparent approach.',blocks:[['What this website stores','This website stores your privacy choice in your browser’s local storage under the key havenly-consent. It is used to remember your choice on this device.'],['Essential functionality','Navigation, sliders, accordions and the enquiry form do not require advertising cookies. This website has no added analytics or marketing trackers.'],['External resources','Fonts may be loaded from external services. Photos and interface libraries are served with this website. Your browser sends the information needed to request those assets. These requests are separate from our locally stored preference.'],['Managing your preference','Use Cookie settings in the footer to reopen the privacy card. You can also clear website data through your browser settings. Accept and Essential only currently enable the same necessary website functions.'],['Questions',`Contact <a data-email href="mailto:${esc(C.email)}">${esc(C.email)}</a> if you have questions about storage on this website.`]]}
};
legalContent.privacy.blocks.splice(5,0,['Information to leave out','A general description of your property is enough for an initial enquiry. Do not include alarm codes, lock credentials, detailed absence schedules or footage of other people. If further information is needed, ask how it will be handled before sharing it.'],['Email correspondence','We use the email address you provide to reply to your enquiry. If you contact us again, refer to the original conversation so that your request can be understood in context.'],['Changes to your enquiry','If your priorities or contact details change, send a correction by email. You can also tell us that you no longer wish to explore an introduction.']);
legalContent.terms.blocks.splice(4,0,['Comparing proposals','Ask a provider to separate equipment costs, installation work, recurring subscriptions and optional support. Confirm what is included and retain a copy of the agreed proposal.'],['Planning illustrations','Interactive camera frames, recording choices and other visual controls are planning aids. They do not operate equipment, measure real coverage or verify that a particular system is suitable for your property.'],['Illustrative prices','Example plans show how monthly costs may be presented. They are not binding quotations. A provider must confirm the actual equipment, installation and recurring charges before any purchase.']);
legalContent.cookies.blocks.splice(3,0,['Storage on shared devices','The preference is stored in the current browser. Another browser, a private browsing session or a different device may show the preference card again. Clearing site data also removes the stored choice.'],['What the controls do','Accept and Essential only record your preference without changing the available navigation or enquiry features. Cookie settings reopens the card so you can choose again. No advertising consent is used to activate hidden marketing scripts.'],['External links','Links to credits and other websites take you to services with their own storage practices. Review their information if you choose to visit them.']);
function legal(key){let d=legalContent[key];return `${wrap('legal-hero','legal-hero navy photo-title',`<h1>${d.title}</h1><p>${d.intro}</p>`)}${wrap('legal-content','',`<div class="legal-layout"><aside><nav aria-label="On this page">${d.blocks.map((b,i)=>`<a href="#legal-${i}">${b[0]}</a>`).join('')}</nav></aside><article>${d.blocks.map((b,i)=>`<div id="legal-${i}"><h2>${b[0]}</h2><p>${b[1]}</p></div>`).join('')}</article></div>`)}`;}
function credits(){return wrap('credits','',`${heading('Image & icon credits.')}<p>Visual direction inspired by Blackcats by Commonsupport. Reference photography and the Blackcats mark are provided by Commonsupport. The home and equipment illustrations were created for this website. Reference portraits illustrate service roles and do not represent our employees.</p><div class="credits-list"><a href="https://www.axis.com/">Axis Communications photography</a><a href="https://ajax.systems/">Ajax Systems equipment imagery</a><a href="assets/photo-sources.json">Photography source records</a><a href="https://www.flaticon.com/authors/photo3idea-studio">Camera icon: photo3idea_studio</a><a href="https://www.flaticon.com/authors/those-icons">Shield icon: Those Icons</a><a href="https://www.flaticon.com/authors/freepik">Privacy, email, motion, siren and lock: Freepik</a><a href="https://www.flaticon.com/authors/kiranshastry">House: Kiranshastry</a><a href="https://www.flaticon.com/authors/itim2101">Settings: itim2101</a><a href="https://www.flaticon.com/authors/ehtisham-abid">Check: Ehtisham Abid</a><a href="https://www.flaticon.com/authors/good-ware">User: Good Ware</a><a href="https://www.flaticon.com/authors/smashicons">Key: Smashicons</a><a href="https://el.commonsupport.com/newwp/blackcats/body-guard/">Commonsupport</a><a href="https://www.flaticon.com/">Flaticon — icon credits</a></div>`);}
function choiceDeck(id,items){return `<div class="choice-deck" data-choice-deck>${items.map((x,i)=>`<button class="choice-tile ${i?'':'active'}" aria-pressed="${!i}" data-choice="${i}">${id==='methods'?`<span class="access-watermark" aria-hidden="true">${brandMark()}</span>`:''}${icon(x[0])}<strong>${x[1]}</strong><span>${x[2]}</span></button>`).join('')}</div>`;}
function disclosureCards(items){return `<div class="disclosure-grid">${items.map(x=>`<details><summary>${icon(x[0])}<strong>${x[1]}</strong><span class="plus"></span></summary><p>${x[2]}</p></details>`).join('')}</div>`;}
function aboutExtras(part){const perspective=wrap('our-perspective','perspective-section',`<div class="perspective-grid"><div class="perspective-heading">${heading('People. Property. Perspective.','A useful introduction starts with understanding what matters to you.')}<a class="text-link" href="contact.html">Bring your questions</a></div>${[['house','A home, not a template','A flat, a family home and a shared entrance each deserve a different conversation. Start with the layout, the people who use it and the equipment already in place.'],['user','Room for your routine','Visitors, deliveries and time away help shape the questions worth asking. Explore access, privacy and the everyday settings that would make sense for your household.']].map(x=>`<article tabindex="0"><h3>${x[1]}</h3><p>${x[2]}</p><span class="outline-word" aria-hidden="true">${[0,1].map(()=>`<span>${x[1]} · Thoughtfully explored · </span>`).join('')}</span></article>`).join('')}</div>`);const journey=wrap('your-journey','journey-section soft',`<div class="journey-layout"><div>${heading('From curious to confident.','Select a step to see how an enquiry develops.')}<p>Explore at your own pace. Any introduction, proposal or agreement is a separate decision.</p></div><div class="journey-stages">${disclosureCards([['camera','Explore the possibilities','Read about cameras, alarms and smart access. Compare the practical questions before selecting equipment.'],['email','Share your priorities','Describe the property and the areas you want to discuss. We respond by email and explain possible next steps.'],['check','Consider the proposal','If an independent provider is introduced, review their scope, charges and support. There is no obligation to proceed.']])}</div></div>`);return part==='perspective'?perspective:journey;}

function serviceExtras(s){if(s.key==='cameras')return wrap('recording-routine','recording-section navy',`<div class="compact-heading">${heading('Keep the moments<br>that matter.')}<p>Choose a starting point. Confirm storage, retention and subscription details with your provider.</p></div>${choiceDeck('recording',[['motion','Event recording','A focused starting point for movement-triggered clips.'],['camera','Continuous recording','A fuller timeline with storage capacity to consider.'],['privacy','Privacy schedules','Explore when recording should pause in shared spaces.']])}<p class="choice-response" aria-live="polite">Selected: Event recording — A focused starting point for movement-triggered clips.</p>`);if(s.key==='smart-access')return wrap('access-methods','access-methods soft',`${heading('Every entrance. A personal preference.','Select a method to explore its everyday considerations.',true)}${choiceDeck('methods',[['key','Physical key','Check whether the chosen lock retains a mechanical backup.'],['lock','Personal code','Ask about unique codes, temporary schedules and removal.'],['settings','Secure app','Review account protection, permissions and lost-device recovery.']])}<p class="choice-response" aria-live="polite">Selected: Physical key — Check whether the chosen lock retains a mechanical backup.</p><div class="choice-photos" aria-label="Smart access examples">${img('access','','Smart entrance lock')}${img('entrance','','Secure home entrance')}</div>`);return '';}


function contactCards(){return wrap('enquiry-details','contact-details',`<div class="contact-detail-grid">${[['email','A useful first message','Describe the areas you want to explore and any equipment already installed.','A few practical details help us understand the right starting point for your enquiry.'],['privacy','Share with confidence','Keep entry codes, passwords and private security credentials out of your message.','You can ask about the enquiry process before providing any further property details.'],['check','A choice at every step','Review each introduction or proposal at your own pace.','An enquiry is a conversation, not a commitment to buy. Any service agreement is made directly with a provider.']].map(x=>`<details><summary>${icon(x[0])}<span class="contact-detail-copy"><strong>${x[1]}</strong><span class="detail-lead">${x[2]}</span></span><span class="plus"></span></summary><div class="contact-detail-extra"><p>${x[3]}</p></div></details>`).join('')}</div>`);}

function serviceExplorer(){return wrap('service-explorer','explorer-section',`${heading('Choose your direction.','Explore each service, then take a closer look.',true)}<div class="service-explorer">${services.map((s,i)=>`<article class="explorer-panel ${i?'':'is-open'}"><h3><button class="explorer-toggle" aria-expanded="${!i}" aria-controls="explorer-${s.key}">${icon(s.icon)}<span>${s.name}</span><span class="plus"></span></button></h3><div class="explorer-detail" id="explorer-${s.key}" ${i?'inert':''}><div class="explorer-photos">${img([['camera','driveway'],['alarm','living'],['access','entrance']][i][0])}${img([['camera','driveway'],['alarm','living'],['access','entrance']][i][1])}</div><div class="explorer-description"><p>${s.description} Review the practical details before choosing equipment.</p>${btn('Explore',s.key+'.html')}</div></div></article>`).join('')}</div>`);}
function panorama(){return wrap('one-home','panorama-section',`<div class="panorama" data-panorama><div class="panorama-images">${img('entrance','panorama-image current','Video doorbell installed beside an entrance')}${img('entrance','panorama-image','Video doorbell installed beside an entrance')}</div><div class="panorama-grid">${[['entrance','A welcome','Entrances & visitors','The way people arrive helps shape your access choices.'],['driveway','A wider view','Driveways & approaches','Consider light, distance and where useful coverage begins.'],['garden','Beyond the door','Gardens & side paths','Outdoor spaces deserve a thoughtful viewing angle.'],['living','A private space','Rooms & daily routines','Keep privacy controls close to everyday decisions.']].map((x,i)=>`<button data-panorama-key="${x[0]}" aria-pressed="${!i}" class="${i?'':'active'}"><span>${x[1]}</span><strong>${x[2]}</strong><p>${x[3]}</p>${icon(['key','camera','house','privacy'][i])}</button>`).join('')}</div></div>`);}
const zoneScenes={cameras:[['driveway','Outdoor camera','Watch the approach','Compare entrance distance, passing traffic and night-time lighting before choosing a camera position.'],['entrance','Video doorbell','See the arrival','Discuss framing that captures visitors while respecting neighbouring windows and shared paths.'],['sideDoor','Camera installation','Plan the installation','Look at foliage, weather exposure and access to power around the edge of the property.']],alarms:[['living','Motion sensor','A routine-aware room','Plan motion sensors around frequently used routes, pets, heating sources and shared household spaces.'],['hallway','Alarm keypad','Time to come home','Ask how entry delays, door sensors and your everyday route work together when you return.'],['window','Window contact','Look beyond the doorway','Accessible windows and separate zones may need different settings for home and away modes.']],'smart-access':[['entrance','Video entry','A considered welcome','Review lock compatibility, door alignment and a backup entry method before choosing connected access.'],['porch','Entry keypad','Everyday controls','Discuss accessible controls, individual permissions and a secure way to manage everyday arrivals.'],['monitoring','Supervised access','A coordinated response','Explore access records, authorised users and how a provider can help review security events.']]};
function cameraConsole(s){const scenes=zoneScenes[s.key];return wrap('zone-view','zone-view-section',`<div class="camera-console" data-console="${s.key}"><div class="console-screen"><div class="console-visual">${img(scenes[0][0],'console-image current',scenes[0][1])}${img(scenes[0][0],'console-image',scenes[0][1])}</div><span class="console-tag">SECURITY IN FOCUS</span><div class="console-reticle" aria-hidden="true"></div><div class="console-caption"><strong data-console-title>${scenes[0][2]}</strong><p data-console-copy>${scenes[0][3]}</p></div></div><aside class="console-controls"><div class="console-brand">${icon(s.icon)}<span>Explore the view</span></div><div class="console-zones">${scenes.map((x,i)=>`<button data-console-zone="${i}" aria-pressed="${!i}" class="${i?'':'active'}"><span>${x[1]}</span><span class="zone-status">${i?'View detail':'Selected'}</span></button>`).join('')}</div><label class="console-zoom">Look closer <output>1.0×</output><input type="range" min="10" max="16" step="1" value="10" aria-label="Preview zoom"></label><p class="console-footnote">Explore real security installations. This is a visual guide, not a live camera feed.</p></aside></div>`);}
const protectionPlans={cameras:[['At the entrance','A useful first view','Frame arrivals clearly without recording more than you need.','Camera placement','Review angle, mounting height and strong backlighting near the doorway.','Privacy boundaries','Ask about masking neighbouring windows and restricting shared account access.','Recording choices','Compare saved clips, retention periods and the cost of cloud features.','entrance'],['Around the property','A wider perspective','Connect useful viewing areas to the way you use the outside of your home.','Lighting','Discuss low-light detail and whether existing outdoor lighting is sufficient.','Connections','Confirm power, Wi-Fi strength or network cabling before selecting hardware.','Weather','Check outdoor ratings and keep foliage away from the intended view.','garden'],['Inside the home','Privacy stays central','Consider the rooms where a camera adds value and the rooms that should remain private.','Shared spaces','Agree on placement with the people who use the room every day.','Control','Compare schedules, physical shutters and quick ways to pause recording.','Access','Review user permissions and how lost-device access can be removed.','living']],alarms:[['Doors & windows','Start at the boundary','Explore accessible entry points and the sensors that suit each opening.','Door contacts','Check fitting, alignment and how faults or low batteries are reported.','Window sensors','Discuss accessible windows and how ventilation affects your settings.','Entry delay','Plan enough time to enter and disarm without avoidable alerts.','hallway'],['Shared rooms','Fit the household','The most useful sensor plan works around people, pets and daily routines.','Motion detection','Ask how room shape and furniture affect sensor coverage.','Home modes','Consider which zones should remain active when someone is inside.','Notifications','Choose who receives alerts and how they would respond.','living'],['When you are away','Understand the response','Knowing what happens after an alert matters as much as detecting one.','Your response','Agree who can check an alert if you are unable to do so.','Monitoring','Ask a separate provider about procedures, availability and contract terms.','Continuity','Review backup power, communication and maintenance requirements.','window']],'smart-access':[['Family access','A door that fits your day','Explore how each household member would enter and manage their own access.','Compatibility','Have the existing door and locking mechanism checked before buying.','Permissions','Discuss individual access and a simple way to remove old permissions.','Fallback','Confirm how to enter if a battery, device or connection is unavailable.','entrance'],['Guest visits','Welcome with boundaries','Temporary access can be convenient when the controls are clear.','Timing','Ask whether codes can start and expire on a schedule.','Removal','Check how a guest credential can be revoked immediately.','Visibility','Understand what access history is recorded and who can see it.','porch'],['Side entrances','The whole arrival route','A secondary door may need a different approach from the main entrance.','Exposure','Review weather, daily wear and suitable hardware.','Door condition','Check smooth mechanical operation and alignment.','Backup entry','Keep an agreed alternative route available when needed.','porch']]};
function protectionTabs(s){const rows=protectionPlans[s.key];return wrap('protection-plans','protection-plans-section',`<div class="protection-tabs" data-protection="${s.key}"><div class="protection-tablist" role="tablist" aria-label="${s.name} planning areas">${rows.map((x,i)=>`<button role="tab" id="protect-tab-${i}" aria-controls="protect-panel-${i}" aria-selected="${!i}" tabindex="${i?-1:0}" data-protect="${i}">${icon(['house','privacy','key'][i])}${x[0]}</button>`).join('')}</div>${rows.map((x,i)=>`<div class="protection-panel" role="tabpanel" id="protect-panel-${i}" aria-labelledby="protect-tab-${i}" ${i?'hidden':''}><div class="protection-photo">${img(x[9])}</div><div class="protection-copy"><h2>${x[1]}</h2><p>${x[2]}</p><div class="protection-points">${[3,5,7].map(n=>`<div><h3>${x[n]}</h3><p>${x[n+1]}</p></div>`).join('')}</div><a class="text-link" href="contact.html?service=${s.key}">Discuss these priorities</a></div></div>`).join('')}</div>`);}
function referenceHome(){return wrap('home-in-context','context-section',`<div class="context-layout"><div class="context-collage">${img('garden','context-main')}${img('consult','context-inset')}<span class="context-seal">${icon('house')}Your home.<br>Your priorities.</span></div><div>${heading('See the whole picture.','Home security starts with the way you live, not a list of devices.')}<p>From the first visitor at the door to a quiet evening inside, each part of your property brings a different set of questions.</p><div class="context-points"><button data-context="entrance">${icon('key')} A welcoming entrance</button><button data-context="garden">${icon('camera')} A considered outside view</button><button data-context="living">${icon('privacy')} Privacy in shared spaces</button></div><p>Explore one area at a time and bring your priorities to a provider who can assess the practical details.</p></div></div>`);}
function homeRibbon(){return wrap('a-thoughtful-brief','brief-ribbon-section',`<div class="brief-ribbon"><div>${heading('A more useful brief.','Bring the details that help a provider understand your home.')}</div>${[['house','Your property','Home type, entrances and existing equipment.'],['user','Your routine','People, visitors and the spaces you use most.'],['shield','Your priorities','The outcomes you want to explore first.']].map(x=>`<a href="contact.html">${icon(x[0])}<strong>${x[1]}</strong><p>${x[2]}</p></a>`).join('')}</div>`);}
function serviceReference(s,part){
 if(s.key==='cameras'&&part===0)return wrap('camera-perspectives','camera-perspectives-section',`<div class="photo-mosaic">${[['camera','Equipment'],['driveway','Approaches'],['garden','Outside'],['living','Inside']].map(x=>`<button data-mosaic="${x[1]}">${img(x[0])}<span>${x[1]}</span></button>`).join('')}<div class="mosaic-copy">${heading('A view with purpose.','Different spaces deserve different conversations.')}<p id="mosaic-description" aria-live="polite">Explore equipment, approaches, outdoor areas and shared rooms to see what deserves attention.</p><a class="text-link" href="contact.html?service=cameras">Talk about your property</a></div></div>`);
 if(s.key==='cameras')return wrap('camera-questions','camera-questions-section navy',`<div class="outline-strip">${[['camera','Detail & distance','Ask what detail will be visible at the distance that matters.'],['motion','Movement & light','Review changing light, passing traffic and useful notifications.'],['privacy','Storage & access','Confirm retention, account permissions and recurring charges.']].map(x=>`<details><summary>${icon(x[0])}<span class="ref-card-copy"><strong>${x[1]}</strong><span>${x[2]}</span></span><span class="plus"></span></summary><div class="reference-reveal">Ask your provider to demonstrate these settings before you agree on the equipment.</div></details>`).join('')}</div>`);
 if(s.key==='alarms'&&part===0)return wrap('alarm-foundations','alarm-foundations-section',`<div class="foundation-strip">${[['house','Around your routine','Describe entrances, pets and the rooms used throughout the day.'],['alarm','Clear notifications','Review who receives an alert and what action they can take.'],['settings','Ongoing care','Ask about battery changes, fault reports and maintenance.']].map(x=>`<article tabindex="0">${icon(x[0])}<h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div>`);
 if(s.key==='alarms')return wrap('alarm-conversations','alarm-conversations-section',`<div class="conversation-layout"><div class="conversation-photo">${img('consult')}<span>${icon('alarm')}</span></div><div>${heading('Start with better questions.')}<div class="conversation-switch"><button class="active" data-conversation="household" aria-pressed="true">Your household</button><button data-conversation="provider" aria-pressed="false">Your provider</button></div><div class="conversation-columns" aria-live="polite"><div><h3 data-conv-title>What happens at home?</h3><p data-conv-copy>Think about who enters, when rooms are occupied and the pets or visitors a sensor plan should consider.</p></div><div><h3 data-conv-title>Who sees the alert?</h3><p data-conv-copy>Consider who can respond to a notification and what should happen when nobody is available.</p></div></div></div></div>`);
 if(part===0)return wrap('access-details','access-details-section',`<div class="access-collage"><div class="access-photos">${img('access')}${img('entrance')}</div><div>${heading('Every detail at the door.','A good fit starts with the mechanism already in place.')}<p>Connected access should complement a door that closes and locks smoothly. Discuss the material, dimensions and current hardware before choosing a model.</p><div class="access-chips">${['Door alignment','Lock compatibility','Backup entry'].map(t=>`<span>${icon('check')}${t}</span>`).join('')}</div><a class="btn" href="contact.html?service=smart-access">Explore your entrance</a></div></div>`);
 return wrap('access-decisions','access-decisions-section soft',`<div class="access-decisions-layout"><div>${heading('Make access<br>feel natural.','Open a topic to prepare your next conversation.')}</div><div class="access-decision-rows">${[['People','Assign suitable permissions to family members and keep a clear process for removing access.'],['Visitors','Explore temporary credentials, scheduled access and how to revoke a code when plans change.'],['Everyday use','Compare how a key, code and app would work when carrying shopping or arriving in bad weather.']].map(x=>`<details><summary>${x[0]}<span class="plus"></span></summary><p>${x[1]}</p></details>`).join('')}</div></div>`);
}

