document.querySelectorAll('[data-context]').forEach(b=>b.onclick=()=>{const image=document.querySelector('.context-main');image.src=photos[b.dataset.context];image.alt=b.textContent.trim();if(!reduce)image.animate([{opacity:.35},{opacity:1}],{duration:450})});
const mosaicCopy={Equipment:'Compare lenses, recording choices and how power reaches each camera. Ask which features require an ongoing plan.',Approaches:'Review the distance to the entrance and the lighting around visitors, deliveries and passing vehicles.',Outside:'Consider weather, planting and network connections. Position cameras to focus on your own property.',Inside:'Discuss shared rooms, recording schedules and privacy controls with the people who use the space.'};document.querySelectorAll('[data-mosaic]').forEach(b=>{const select=()=>document.querySelector('#mosaic-description').textContent=mosaicCopy[b.dataset.mosaic];b.onclick=select;b.onfocus=select});
const conversationCopy={household:[['What happens at home?','Think about who enters, when rooms are occupied and the pets or visitors a sensor plan should consider.'],['Who sees the alert?','Consider who can respond to a notification and what should happen when nobody is available.']],provider:[['What is included?','Request a clear breakdown of equipment, installation, optional monitoring and ongoing maintenance charges.'],['What happens next?','Ask how a fault is reported, how support is reached and what the agreed response procedure covers.']]};document.querySelectorAll('[data-conversation]').forEach(b=>b.onclick=()=>{const root=b.closest('.conversation-layout'),rows=conversationCopy[b.dataset.conversation];root.querySelectorAll('[data-conversation]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});root.querySelectorAll('[data-conv-title]').forEach((x,i)=>x.textContent=rows[i][0]);root.querySelectorAll('[data-conv-copy]').forEach((x,i)=>x.textContent=rows[i][1])});
document.querySelectorAll('.outline-strip details,.access-decision-rows details').forEach(d=>{let wanted=d.open,animation;d.querySelector('summary').addEventListener('click',e=>{e.preventDefault();wanted=!wanted;if(reduce){d.open=wanted;return}const from=d.getBoundingClientRect().height;animation?.cancel();d.open=true;const expanded=d.getBoundingClientRect().height;d.open=false;const collapsed=d.getBoundingClientRect().height;d.open=true;d.style.overflow='hidden';animation=d.animate({height:[from+'px',(wanted?expanded:collapsed)+'px']},{duration:380,easing:'cubic-bezier(.22,1,.36,1)'});animation.onfinish=()=>{d.open=wanted;d.style.overflow='';animation=null}})});
